-- 2026 教育产品目录价格字段及租户 1 目录配置（受控开发环境）。
-- 依赖：V001-V218、zsjos_product、zsjos_product_sku。
-- 不删除产品、SKU或历史业务快照；可重复执行。旧目录停用需单独核对。
-- 本文件包含已确认的业务目录，不适用于无业务数据的生产 bootstrap。
-- 顺序：字段、分类、SPU、属性、属性值、SKU。DDL 自动提交；回退需执行前备份。
SET NAMES utf8mb4;

SET @ddl = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `zsjos_product_sku` ADD COLUMN `retail_price` decimal(10,2) DEFAULT NULL COMMENT ''零售价'' AFTER `price`', 'SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_product_sku' AND column_name='retail_price'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `zsjos_product_sku` ADD COLUMN `min_deal_price` decimal(10,2) DEFAULT NULL COMMENT ''最低成交价'' AFTER `retail_price`', 'SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_product_sku' AND column_name='min_deal_price'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `zsjos_product_sku` ADD COLUMN `min_deal_type` varchar(32) DEFAULT NULL COMMENT ''最低成交价类型 FIXED/DISCOUNT_RATE/NEGOTIABLE'' AFTER `min_deal_price`', 'SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_product_sku' AND column_name='min_deal_type'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `zsjos_product_sku` ADD COLUMN `min_deal_rate` decimal(8,4) DEFAULT NULL COMMENT ''最低成交折扣'' AFTER `min_deal_type`', 'SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_product_sku' AND column_name='min_deal_rate'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `zsjos_product_sku` ADD COLUMN `exam_fee` decimal(10,2) DEFAULT NULL COMMENT ''考试费'' AFTER `min_deal_rate`', 'SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_product_sku' AND column_name='exam_fee'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `zsjos_product_sku` ADD COLUMN `price_unit` varchar(32) DEFAULT ''PACKAGE'' COMMENT ''计价单位'' AFTER `exam_fee`', 'SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_product_sku' AND column_name='price_unit'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `zsjos_product_sku` ADD COLUMN `pricing_note` varchar(1000) DEFAULT NULL COMMENT ''价格说明'' AFTER `price_unit`', 'SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_product_sku' AND column_name='pricing_note'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;


